// Card numbers are never needed, so they are removed before anything is scored, stored or
// alerted (Slack and the manager email quote the customer's words). 13-19 digits, spaces or
// dashes allowed, Luhn-checked so phone numbers and amounts are left alone.
function maskCards(text) {
  return text.replace(/(?<![\d+])\d(?:[ -]?\d){12,18}(?!\d)/g, (m) => {
    const d = m.replace(/\D/g, '');
    let sum = 0;
    for (let i = 0; i < d.length; i++) {
      let n = Number(d[d.length - 1 - i]);
      if (i % 2 === 1) { n *= 2; if (n > 9) n -= 9; }
      sum += n;
    }
    return sum % 10 === 0 ? `[card number removed, ending ${d.slice(-4)}]` : m;
  });
}


// Draft evaluation input. Mirrors what 02's Draft reply reads from Decide route, without Airtable:
// the reply (card numbers masked, as in 02's Read reply), the customer's name, branch, whether
// it is a repeat complaint, its severity, and the check-in problem (background only).
const b = $input.first().json.body ?? {};
return [{ json: {
  raw_text: maskCards(String(b.raw_text ?? '').trim()),
  customer_name: String(b.customer_name ?? 'Ada Obi'),
  location: String(b.location ?? 'Ikoyi'),
  repeat_customer: b.repeat_customer === true,
  severity: Number(b.severity ?? 2),
  service: String(b.service ?? ''),
} }];

