// Returns the draft, or the error if drafting failed (Draft reply continues on error, as in 02).
const r = $('Draft reply').first().json;
const input = $('Read input').first().json;
return [{ json: {
  draft: String(r.text ?? '').trim(),
  error: r.error ? String(r.error.message ?? r.error) : null,
  raw_text: input.raw_text,
} }];
